from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('RGB')); mask=im.mean(2)<100
h,w=mask.shape; seen=np.zeros_like(mask); comps=[]
for y,x in zip(*np.where(mask)):
 if seen[y,x]:continue
 st=[(y,x)];seen[y,x]=1;xs=[];ys=[]
 while st:
  yy,xx=st.pop();xs.append(xx);ys.append(yy)
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    a,b=yy+dy,xx+dx
    if 0<=a<h and 0<=b<w and mask[a,b] and not seen[a,b]:seen[a,b]=1;st.append((a,b))
 if len(xs)>5:comps.append((len(xs),min(xs),min(ys),max(xs),max(ys)))
print('components', sorted(comps,reverse=True)[:50])
